"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
ELAPSED_UNITS = {"minute": 60, "hour": 3600}
UNITS = {spelling: unit for unit in ("day", "week", "month", *ELAPSED_UNITS)
         for spelling in (unit, unit + "s")}

POSITIVE = r"[1-9][0-9]*"
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
TIME = r"(?:[01][0-9]|2[0-3]):[0-5][0-9]"
LOCAL_TIME = re.compile(rf"{DATE}T{TIME}")
DURATION = re.compile(rf"({POSITIVE}d)?({POSITIVE}h)?({POSITIVE}m)?")


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    anchor: dt.datetime = None  # minute/hour rules only
    until: dt.date = None
    times: int = None

    @property
    def elapsed_step(self):
        if self.anchor is not None:
            return self.every * ELAPSED_UNITS[self.unit]


def parse_duration(word):
    """Return the duration in minutes, or None for invalid input."""
    match = DURATION.fullmatch(word.casefold()) if isinstance(word, str) else None
    if not match or not word:
        return None
    # Decimal conversion also accepts integers beyond Python's string-to-int digit limit.
    return sum(int(Decimal(part[:-1])) * scale
               for part, scale in zip(match.groups(), (1440, 60, 1)) if part)


def format_duration(minutes):
    days, remainder = divmod(minutes, 1440)
    hours, mins = divmod(remainder, 60)
    return "".join(f"{Decimal(amount)}{unit}"
                   for amount, unit in ((days, "d"), (hours, "h"), (mins, "m")) if amount)


def _positive(word):
    if re.fullmatch(POSITIVE, word):
        return int(Decimal(word))


def parse_date(word):
    if not re.fullmatch(DATE, word):
        raise ValueError("expected a date")
    return dt.date.fromisoformat(word)


def parse_local(text):
    if not isinstance(text, str) or not LOCAL_TIME.fullmatch(text):
        raise ValueError("expected a local date and time")
    return dt.datetime.fromisoformat(text)


def _time(word):
    if not re.fullmatch(TIME, word):
        raise ValueError("invalid time")
    return dt.time.fromisoformat(word)


def _month_day(word):
    if word == "last":
        return word
    if re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        return int(word)
    raise ValueError("invalid month day")


def _items(word, parse_item, sort_key=None):
    items = [parse_item(item) for item in word.split(",")]
    if len(set(items)) == len(items):
        return sorted(items, key=sort_key)


class _Words:
    def __init__(self, text):
        self.text = text
        self.tokens = list(re.finditer(r"[^ \t]+", text))
        self.index = 0

    def peek(self):
        if self.index < len(self.tokens):
            return self.tokens[self.index].group().casefold()

    def fail(self, message):
        position = self.tokens[self.index].start() if self.index < len(self.tokens) else len(self.text)
        raise RuleSyntaxError(message, position, self.text)

    def expect(self, keyword):
        if self.peek() != keyword:
            self.fail(f"expected '{keyword}'")
        self.index += 1

    def convert(self, what, parse):
        word = self.peek()
        if word is None:
            self.fail(f"expected {what}, found end of rule")
        try:
            value = parse(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            self.fail(f"expected {what}, found {word!r}")
        self.index += 1
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise PlanError("rule text must be a string")
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    word = w.peek()
    if word is not None and re.fullmatch(r"[0-9]+", word):
        rule.every = w.convert("a count", _positive)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    elapsed = rule.unit in ELAPSED_UNITS
    if not elapsed:
        if w.peek() == "on":
            if rule.unit == "day":
                w.fail("'on' is not allowed for day rules")
            w.expect("on")
            if rule.unit == "month":
                rule.on = w.convert("month days", lambda s: _items(s, _month_day, lambda day: 32 if day == "last" else day))
            else:
                rule.on = w.convert("weekdays", lambda s: _items(s, WEEKDAYS.index))
        w.expect("at")
        rule.at = w.convert("times", lambda s: _items(s, _time))
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    if elapsed:
        rule.anchor = w.convert("a local date-time", lambda s: parse_local(s.upper()))
        rule.start = rule.anchor.date()
    else:
        rule.start = w.convert("a date", parse_date)
    if w.peek() == "until":
        w.expect("until")

        def parse_until(word):
            day = parse_date(word)
            if day >= rule.start:
                return day

        rule.until = w.convert("a date on or after 'from'", parse_until)
    elif w.peek() == "times":
        w.expect("times")
        rule.times = w.convert("a count", _positive)
    if w.peek() is not None:
        w.fail(f"unexpected token {w.peek()!r}")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    unit = rule.unit if rule.every == 1 else rule.unit + "s"
    out = ["every", str(Decimal(rule.every)), unit]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    if rule.anchor is None:
        out += ["at", ",".join(t.isoformat(timespec="minutes") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    start = rule.anchor.isoformat(timespec="minutes") if rule.anchor is not None else rule.start.isoformat()
    out += ["from", start]
    if rule.until is not None:
        out += ["until", rule.until.isoformat()]
    if rule.times is not None:
        out += ["times", str(Decimal(rule.times))]
    return " ".join(out)
"""Plan loading (SPEC.md sections 1 and 5)."""

import re
from collections import defaultdict
from dataclasses import dataclass
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError, available_timezones

from .errors import PlanError, RuleSyntaxError
from .expand import expand
from .holidays import Holidays
from .instants import local_instant, parse_utc_key
from .rules import DATE, Rule, parse_duration, parse_local, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int
    holiday: str
    holidays: Holidays


@dataclass
class Override:
    rule: RuleDef
    key: str
    action: str
    to: int = None   # UTC seconds
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # (rule id, key) -> Override
    min_segment: int


def _zone(name):
    if not isinstance(name, str):
        raise PlanError("timezone must be an IANA zone name")
    if name in ("localtime", "posixrules") or name.startswith(("posix/", "right/")):
        raise PlanError(f"unknown timezone {name!r}")
    # Deep unknown paths can exhaust the recursion limit in ZoneInfo's
    # package fallback. Check the installed database first for those names.
    if name.count("/") > 2 and name not in available_timezones():
        raise PlanError(f"unknown timezone {name!r}")
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, OSError, ValueError) as exc:
        raise PlanError(f"unknown timezone {name!r}") from exc


def _duration(word):
    if not isinstance(word, str):
        raise PlanError("duration must be a string")
    minutes = parse_duration(word)
    if minutes is None:
        raise PlanError(f"invalid duration {word!r}")
    return minutes


def _load_rule(index, item, default_tz, rules, holidays):
    if not isinstance(item, dict):
        raise PlanError(f"rule #{index} must be an object")
    rid = item.get("id")
    if not isinstance(rid, str):
        raise PlanError(f"rule #{index} id must be a string")
    if not re.fullmatch(r"[a-zA-Z0-9_-]+", rid):
        raise PlanError(f"rule #{index} has an invalid id {rid!r}")
    if rid in rules:
        raise PlanError(f"duplicate rule id {rid!r}")

    try:
        rule = parse_rule(item.get("rule"))
        tz = _zone(item["timezone"]) if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError("priority must be an integer")
        holiday = item.get("holiday", "keep")
        if not isinstance(holiday, str) or holiday not in ("keep", "skip", "shift"):
            raise PlanError("holiday must be 'keep', 'skip', or 'shift'")
        if holiday == "shift" and rule.anchor is not None:
            raise PlanError("minute and hour rules cannot shift on holidays")
    except RuleSyntaxError as exc:
        raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, exc.text) from exc
    except PlanError as exc:
        raise PlanError(f"rule {rid}: {exc}") from exc
    return RuleDef(index, rid, rule, tz, priority, holiday, holidays)


def _load_override(item, rules):
    if not isinstance(item, dict):
        raise PlanError("override must be an object")
    rid = item.get("rule")
    if not isinstance(rid, str):
        raise PlanError("override rule id must be a string")
    if rid not in rules:
        raise PlanError(f"override for unknown rule {rid!r}")
    ruledef = rules[rid]
    key = item.get("key")
    if not isinstance(key, str):
        raise PlanError(f"rule {rid}: override key must be a string")
    if len(ruledef.rule.at) == 1 and re.fullmatch(DATE, key):
        key += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
    try:
        if ruledef.rule.anchor is not None:
            coordinate = parse_utc_key(key)
        else:
            coordinate = parse_local(key).toordinal()
    except ValueError as exc:
        raise PlanError(f"rule {rid}: invalid override key {key!r}") from exc

    action = item.get("action")
    if not isinstance(action, str):
        raise PlanError(f"rule {rid}: override action must be a string")
    if action not in ("cancel", "move"):
        raise PlanError(f"rule {rid}: unknown override action {action!r}")
    override = Override(ruledef, key, action)
    if action == "move":
        try:
            override.to = local_instant(parse_local(item.get("to")), ruledef.tz)
        except ValueError as exc:
            raise PlanError(f"rule {rid}: move override needs a valid 'to'") from exc
        if "for" in item:
            try:
                override.minutes = _duration(item["for"])
            except PlanError as exc:
                raise PlanError(f"rule {rid}: {exc}") from exc
    return override, coordinate


def _validate_override_keys(ruledef, targets):
    # Historical UTC offsets can have seconds. An elapsed key identifies the
    # UTC minute containing the start, which is unique within the rule.
    precision = 59 if ruledef.rule.anchor is not None else 0
    if ruledef.rule.times is None:
        for key, coordinate in targets.items():
            if not any(occ.key == key for occ in expand(ruledef, coordinate, coordinate + precision)):
                raise PlanError(f"rule {ruledef.id}: override key {key!r} does not name an occurrence")
        return

    remaining = set(targets)
    for occ in expand(ruledef, min(targets.values()), max(targets.values()) + precision):
        remaining.discard(occ.key)
        if not remaining:
            return
    key = min(remaining)
    raise PlanError(f"rule {ruledef.id}: override key {key!r} does not name an occurrence")


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    holidays = Holidays(raw.get("holidays", []))

    items = raw.get("rules")
    if not isinstance(items, list):
        raise PlanError("plan rules must be a list")
    rules = {}
    for index, item in enumerate(items):
        ruledef = _load_rule(index, item, default_tz, rules, holidays)
        rules[ruledef.id] = ruledef

    min_segment = _duration(raw["min_segment"]) if "min_segment" in raw else 0
    items = raw.get("overrides", [])
    if not isinstance(items, list):
        raise PlanError("plan overrides must be a list")
    overrides = {}
    targets = defaultdict(dict)
    for item in items:
        override, coordinate = _load_override(item, rules)
        rid, key = override.rule.id, override.key
        if (rid, key) in overrides:
            raise PlanError(f"rule {rid}: duplicate override for {key!r}")
        overrides[rid, key] = override
        targets[rid][key] = coordinate

    for rid, keys in targets.items():
        _validate_override_keys(rules[rid], keys)
    return Plan(list(rules.values()), overrides, min_segment)
"""Validated, merged holiday ranges, indexed by ordinal date."""

from bisect import bisect_left

from .errors import PlanError
from .rules import parse_date


class Holidays:
    def __init__(self, items):
        if not isinstance(items, list):
            raise PlanError("plan holidays must be a list")
        ranges = []
        for index, item in enumerate(items):
            try:
                if not isinstance(item, str):
                    raise ValueError("expected a date or range")
                start, separator, end = item.partition("..")
                first = parse_date(start).toordinal()
                last = parse_date(end).toordinal() if separator else first
                if last < first:
                    raise ValueError("end precedes start")
            except ValueError as exc:
                raise PlanError(f"invalid holiday at index {index}: {exc}") from exc
            ranges.append((first, last))

        self.ranges = []
        for first, last in sorted(ranges):
            if self.ranges and first <= self.ranges[-1][1] + 1:
                previous, previous_end = self.ranges[-1]
                self.ranges[-1] = (previous, max(previous_end, last))
            else:
                self.ranges.append((first, last))
        self.ends = [last for _, last in self.ranges]

    def containing(self, day):
        index = bisect_left(self.ends, day)
        if index < len(self.ranges) and self.ranges[index][0] <= day:
            return self.ranges[index]

    def overlapping(self, first, last):
        for index in range(bisect_left(self.ends, first), len(self.ranges)):
            start, end = self.ranges[index]
            if start > last:
                break
            yield start, end
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import lcm
from typing import TYPE_CHECKING

from .errors import PlanError
from .instants import DAY_SECONDS, LAST_DAY, format_utc_key, local_day, local_instant

if TYPE_CHECKING:
    from .plan import RuleDef


@dataclass
class Occurrence:
    rule: "RuleDef"
    key: str
    start: int  # UTC seconds
    end: int


def _month_index(day):
    return day.year * 12 + day.month - 1


def _candidate_days(rule, first, last):
    if first > last:
        return
    start = rule.start.toordinal()
    if rule.unit == "day":
        first += (start - first) % rule.every
        for day in range(first, last + 1, rule.every):
            yield dt.date.fromordinal(day)
    elif rule.unit == "week":
        monday = start - rule.start.weekday()
        week = (first - monday) // 7
        week += -week % rule.every
        for active in range(monday + week * 7, last + 1, rule.every * 7):
            for weekday in rule.on:
                day = active + weekday
                if first <= day <= last:
                    yield dt.date.fromordinal(day)
    else:
        first_month = _month_index(dt.date.fromordinal(first))
        last_month = _month_index(dt.date.fromordinal(last))
        first_month += (_month_index(rule.start) - first_month) % rule.every
        # Gregorian dates repeat every 400 years. If a full cycle of active
        # months has no valid day, the rule will never produce a candidate.
        cycle_end = first_month + lcm(4800, rule.every)
        has_valid_day = False
        for month_index in range(first_month, last_month + 1, rule.every):
            if month_index == cycle_end and not has_valid_day:
                return
            year, month = divmod(month_index, 12)
            month += 1
            month_len = calendar.monthrange(year, month)[1]
            days = {month_len if item == "last" else item for item in rule.on
                    if item == "last" or item <= month_len}
            has_valid_day |= bool(days)
            month_start = dt.date(year, month, 1).toordinal() - 1
            for day in sorted(days):
                if first <= month_start + day <= last:
                    yield dt.date.fromordinal(month_start + day)


def _day_slots(day, ruledef):
    seen = set()
    for time in ruledef.rule.at:
        instant = local_instant(dt.datetime.combine(day, time), ruledef.tz)
        if instant not in seen:
            seen.add(instant)
            yield time, instant


def _regular_candidates(ruledef, first, last):
    for day in _candidate_days(ruledef.rule, first, last):
        ordinal = day.toordinal()
        for time, instant in _day_slots(day, ruledef):
            yield ordinal, time, instant


def _shifted_candidates(ruledef, first, last, target):
    rule = ruledef.rule
    if target <= LAST_DAY and (rule.until is None or target <= rule.until.toordinal()):
        taken = {time for _, time, _ in _regular_candidates(ruledef, target, target)}
    else:
        taken = set()

    if len(taken) == len(rule.at):
        return
    # The next date can be outside the output calendar. Keep the instant so
    # an override can still cancel it or move it to a representable date.
    target_day = dt.date.fromordinal(min(target, LAST_DAY))
    extra = (target - target_day.toordinal()) * DAY_SECONDS
    for day, time, _ in _regular_candidates(ruledef, first, last):
        if time not in taken:
            start = local_instant(dt.datetime.combine(target_day, time), ruledef.tz) + extra
            yield day, time, start
            taken.add(time)
            if len(taken) == len(rule.at):
                return


def _calendar_candidates(ruledef, first, last):
    rule = ruledef.rule
    first = max(first, rule.start.toordinal())
    last = min(last, rule.until.toordinal() if rule.until else LAST_DAY)
    if first > last:
        return

    current = rule.start.toordinal() if rule.times is not None else first
    if ruledef.holiday == "keep":
        yield from _regular_candidates(ruledef, current, last)
        return

    for holiday_start, holiday_end in ruledef.holidays.overlapping(current, last):
        yield from _regular_candidates(ruledef, current, holiday_start - 1)
        if ruledef.holiday == "shift":
            # Resolve each destination against the whole holiday block, even
            # when validation asks for a key in the middle of the block.
            source = max(holiday_start, rule.start.toordinal())
            yield from _shifted_candidates(ruledef, source, min(last, holiday_end), holiday_end + 1)
        current = holiday_end + 1
    yield from _regular_candidates(ruledef, current, last)


def _elapsed_candidates(ruledef, first, last):
    rule = ruledef.rule
    step = rule.elapsed_step
    anchor = local_instant(rule.anchor, ruledef.tz)
    skip_holidays = ruledef.holiday == "skip" and bool(ruledef.holidays.ranges)
    until = rule.until.toordinal() if rule.until else None
    if until is not None:
        # The offset is strictly within one day. Near a backward transition
        # a candidate can re-enter the allowed local dates.
        last = min(last, (until + 1) * DAY_SECONDS - 1)
    if rule.times is not None:
        if skip_holidays:
            first = anchor
        else:
            last = min(last, anchor + (rule.times - 1) * step)

    first = max(first, anchor)
    if not skip_holidays and until is None:
        for instant in range(first + (anchor - first) % step, last + 1, step):
            yield instant, None, instant
        return

    while first <= last:
        instant = first + (anchor - first) % step
        if instant > last:
            break
        day = local_day(instant, ruledef.tz)
        holiday = ruledef.holidays.containing(day) if skip_holidays else None
        if holiday:
            # Seek into the last two possible UTC days of the holiday run.
            # A timezone change cannot cross the intervening local dates.
            holiday_start, holiday_end = holiday
            if instant >= holiday_start * DAY_SECONDS:
                first = max(instant + step, (holiday_end - 1) * DAY_SECONDS)
                continue
        if not holiday and (until is None or day <= until):
            yield instant, None, instant
        first = instant + step


def expand(ruledef, first, last):
    """Yield retained candidates in a range of ordinal dates or UTC seconds."""
    if first > last:
        return
    rule = ruledef.rule
    elapsed = rule.anchor is not None
    candidates = (_elapsed_candidates if elapsed else _calendar_candidates)(ruledef, first, last)
    # Without holiday skips, elapsed rules apply the count by bounding the
    # arithmetic progression, so a seek doesn't need to count the prefix.
    limit = rule.times
    if elapsed and not (ruledef.holiday == "skip" and ruledef.holidays.ranges):
        limit = None
    for count, (coordinate, time, start) in enumerate(candidates, 1):
        if coordinate >= first:
            if elapsed:
                try:
                    key = format_utc_key(start)
                except OverflowError as exc:
                    raise PlanError(f"rule {ruledef.id}: UTC key is outside the supported calendar") from exc
            else:
                key = dt.datetime.combine(dt.date.fromordinal(coordinate), time).isoformat(timespec="minutes")
            yield Occurrence(ruledef, key, start, start + rule.minutes * 60)
        if count == limit:
            return


def expand_window(ruledef, start, end):
    """Seek to candidates that can overlap the UTC window."""
    earliest = start - ruledef.rule.minutes * 60
    if ruledef.rule.anchor is not None:
        return expand(ruledef, earliest + 1, end - 1)

    # The nominal start is the UTC start plus an offset strictly within one day.
    first = (earliest - DAY_SECONDS) // DAY_SECONDS + 1
    last = (end + DAY_SECONDS - 1) // DAY_SECONDS + 1
    if ruledef.holiday == "shift":
        preceding = ruledef.holidays.containing(first - 1)
        if preceding:
            first = preceding[0]
    return expand(ruledef, first, last)
"""Parse wall times and convert between local timestamps and UTC seconds."""

import datetime as dt
import re
from functools import lru_cache

from .errors import PlanError
from .rules import DATE, TIME, parse_local

DAY_SECONDS = 86400
LAST_DAY = dt.date.max.toordinal()
LAST_SECOND = LAST_DAY * DAY_SECONDS - 1
UTC_EPOCH = dt.datetime.min.replace(tzinfo=dt.timezone.utc)
BOUND = re.compile(rf"({DATE}T{TIME}(?::[0-5][0-9])?)(Z|([+-])([0-9]{{2}}):([0-9]{{2}}))")


def _wall_seconds(local):
    return ((local.toordinal() - 1) * DAY_SECONDS
            + local.hour * 3600 + local.minute * 60 + local.second)


def local_instant(local, zone):
    # With fold=0, zoneinfo uses the earlier offset for a fold and the
    # pre-transition offset for a gap. The latter shifts the wall time forward.
    offset = local.replace(tzinfo=zone, fold=0).utcoffset()
    return _wall_seconds(local) - int(offset.total_seconds())


def parse_bound(text):
    if not isinstance(text, str):
        raise PlanError("query bounds must be date-time strings")
    match = BOUND.fullmatch(text)
    if match:
        wall, suffix, sign, hours, minutes = match.groups()
        try:
            seconds = _wall_seconds(dt.datetime.fromisoformat(wall))
            if suffix == "Z":
                return seconds
            hours, minutes = int(hours), int(minutes)
            if hours < 24 and minutes < 60:
                offset = hours * 3600 + minutes * 60
                return seconds - offset if sign == "+" else seconds + offset
        except ValueError:
            pass
    raise PlanError(f"invalid date-time {text!r}")


def parse_utc_key(text):
    if not text.endswith("Z"):
        raise ValueError("expected a UTC minute key")
    return _wall_seconds(parse_local(text[:-1]))


@lru_cache(maxsize=4096)
def format_utc_key(instant):
    return (dt.datetime.min + dt.timedelta(seconds=instant)).isoformat(timespec="minutes") + "Z"


@lru_cache(maxsize=4096)
def _utc_datetime(instant):
    return UTC_EPOCH + dt.timedelta(seconds=instant)


def _edge_offset(instant, zone):
    reference = DAY_SECONDS if instant < DAY_SECONDS else LAST_SECOND - DAY_SECONDS
    return int(_utc_datetime(reference).astimezone(zone).utcoffset().total_seconds())


def _local_datetime(instant, zone):
    if 0 <= instant <= LAST_SECOND:
        return _utc_datetime(instant).astimezone(zone)
    # An instant outside UTC's calendar can still have a representable local date.
    offset = _edge_offset(instant, zone)
    local = dt.datetime.min + dt.timedelta(seconds=instant + offset)
    return local.replace(tzinfo=zone)


@lru_cache(maxsize=4096)
def local_day(instant, zone):
    try:
        return _local_datetime(instant, zone).toordinal()
    except OverflowError:
        return (instant + _edge_offset(instant, zone)) // DAY_SECONDS + 1


@lru_cache(maxsize=4096)
def format_timestamp(instant, zone):
    try:
        local = _local_datetime(instant, zone)
        offset = int(local.utcoffset().total_seconds())
        return _format_wall_time(instant, offset)
    except OverflowError as exc:
        raise PlanError("occurrence timestamp is outside the supported calendar") from exc


@lru_cache(maxsize=4096)
def _format_wall_time(instant, offset):
    # Historical zone offsets can include seconds. The wire format has minutes.
    local = dt.datetime.min + dt.timedelta(seconds=instant + offset)
    hours, minutes = divmod(abs(offset) // 60, 60)
    sign = "-" if offset <= -60 else "+"
    return f"{local.isoformat(timespec='seconds')}{sign}{hours:02d}:{minutes:02d}"
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import heapq
from collections import defaultdict

from .errors import PlanError
from .expand import Occurrence, expand_window
from .instants import format_timestamp, parse_bound
from .plan import load_plan


def _window(start, end):
    lo, hi = parse_bound(start), parse_bound(end)
    if hi <= lo:
        raise PlanError("end must be after start")
    return lo, hi


def _collect(plan, start, end):
    for ruledef in plan.rules:
        for occ in expand_window(ruledef, start, end):
            if (occ.start < end and occ.end > start
                    and (ruledef.id, occ.key) not in plan.overrides):
                yield occ

    # Moved keys can be arbitrarily far outside the candidate search range.
    for override in plan.overrides.values():
        if override.action == "move":
            ruledef = override.rule
            minutes = override.minutes if override.minutes is not None else ruledef.rule.minutes
            finish = override.to + minutes * 60
            if override.to < end and finish > start:
                yield Occurrence(ruledef, override.key, override.to, finish)


def _as_dict(occ, start, end):
    try:
        return {
            "rule": occ.rule.id,
            "key": occ.key,
            "start": format_timestamp(start, occ.rule.tz),
            "end": format_timestamp(end, occ.rule.tz),
        }
    except PlanError as exc:
        raise PlanError(f"rule {occ.rule.id}: {exc}") from exc


def occurrences(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _window(start, end)
    found = sorted(_collect(plan, lo, hi),
                   key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in found]


def _winning_segments(occurrences):
    starts = defaultdict(dict)
    boundaries = set()
    for occ in occurrences:
        rank = (-occ.rule.priority, occ.start, occ.rule.index, occ.key)
        ending_at = starts[occ.start]
        previous = ending_at.get(occ.end)
        # The highest-ranked occurrence covers the whole interval of every
        # lower-ranked occurrence with identical endpoints.
        if previous is None or rank < previous[0]:
            ending_at[occ.end] = (rank, occ)
            boundaries.update((occ.start, occ.end))

    active = []
    current = None
    segment_start = None
    for instant in sorted(boundaries):
        for entry in starts.get(instant, {}).values():
            heapq.heappush(active, entry)
        while active and active[0][1].end <= instant:
            heapq.heappop(active)
        winner = active[0][1] if active else None
        if winner is not current:
            if current is not None:
                yield current, segment_start, instant
            current = winner
            segment_start = instant


def agenda(plan, start, end):
    plan = load_plan(plan)
    lo, hi = _window(start, end)
    rows = []
    for occ, left, right in _winning_segments(_collect(plan, lo, hi)):
        lost_time = left != occ.start or right != occ.end
        if lost_time and right - left < plan.min_segment * 60:
            continue
        left, right = max(lo, left), min(hi, right)
        if left < right:
            rows.append(_as_dict(occ, left, right))
    return rows
import codecs
import json
import sys
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError
from .query import agenda, occurrences
from .rules import canonical


def _invalid_constant(text):
    raise ValueError(f"invalid JSON constant {text}")


def _read_plan(path):
    with open(path, "rb") as f:
        data = f.read()

    # JSON starts with ASCII syntax or whitespace. Detect UTF-16/32 from
    # their BOM or from the null bytes in the first code unit.
    if data.startswith((codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE)):
        encoding = "utf-32"
    elif data.startswith((codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE)):
        encoding = "utf-16"
    elif data.startswith(b"\0\0\0"):
        encoding = "utf-32-be"
    elif data[1:4] == b"\0\0\0":
        encoding = "utf-32-le"
    elif data.startswith(b"\0"):
        encoding = "utf-16-be"
    elif data[1:2] == b"\0":
        encoding = "utf-16-le"
    else:
        encoding = "utf-8-sig"
    return json.loads(data.decode(encoding), parse_constant=_invalid_constant,
                      parse_int=lambda s: int(Decimal(s)))


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) == 2 and argv[0] == "canonical":
        run = canonical
        args = (argv[1],)
    elif len(argv) == 4 and argv[0] in ("occurrences", "agenda"):
        command, start, end, path = argv
        try:
            plan = _read_plan(path)
        except (OSError, ValueError, RecursionError) as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1
        run = occurrences if command == "occurrences" else agenda
        args = (plan, start, end)
    else:
        print("usage: python3 -m cadence {occurrences,agenda} START END PLAN.json", file=sys.stderr)
        print("       python3 -m cadence canonical RULE", file=sys.stderr)
        return 1

    try:
        result = run(*args)
    except PlanError as exc:
        print(f"error: {exc}", file=sys.stderr)
        if isinstance(exc, RuleSyntaxError):
            print(exc.text, file=sys.stderr)
            print(" " * exc.position + "^", file=sys.stderr)
        return 2

    if run is canonical:
        print(result)
    elif result:
        for row in result:
            print(row["start"], row["end"], row["rule"], row["key"])
    else:
        print("nothing scheduled")
    return 0
class PlanError(Exception):
    """Invalid plan, override or query argument."""


class RuleSyntaxError(PlanError):
    """Invalid rule text."""

    def __init__(self, message, position, text=None):
        super().__init__(message)
        self.position = position
        self.text = text
